INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('aa200001-cc00-0000-0000-000000000001', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Fès Pottery Wheel Class', 'Hands-on pottery class with a master Fassi ceramicist. Learn the famous blue Fès technique.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 1, '{}', 1, 6, 120, 2, 'active', 'https://images.pexels.com/photos/32422996/pexels-photo-32422996.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200002-cc00-0000-0000-000000000002', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Fès Medina Treasure Hunt', 'A fun, family-friendly treasure hunt through the medina, solving clues and discovering hidden corners.', ARRAY['en','fr','es','it','ary-Latn'], 6, 2, '{}', 2, 8, 150, 1, 'active', 'https://images.pexels.com/photos/28582578/pexels-photo-28582578.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200003-cc00-0000-0000-000000000003', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Traditional Hammam in Fès', 'A traditional Moroccan hammam experience in a historic Fassi bathhouse with scrub and massage.', ARRAY['en','fr','es','ary-Latn'], 12, 1, '{}', 1, 6, 90, 2, 'active', 'https://images.pexels.com/photos/33279021/pexels-photo-33279021.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200004-cc00-0000-0000-000000000004', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Fès Rooftop Sunset & Tea', 'Watch the sun set over the Fès medina from a private rooftop, with mint tea and pastries.', ARRAY['en','fr','es','it','ary-Latn','ber'], 5, 1, '{}', 1, 10, 60, 1, 'active', 'https://images.pexels.com/photos/30906051/pexels-photo-30906051.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200005-cc00-0000-0000-000000000005', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Fès Andalusian Music Evening', 'An evening of live Andalusian music in a restored medana courtyard, with tea and pastries.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 1, '{}', 1, 15, 120, 2, 'active', 'https://images.pexels.com/photos/33344404/pexels-photo-33344404.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200006-cc00-0000-0000-000000000006', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Fès El-Jdid & Royal Palace Walk', 'Guided walk through Fès el-Jdid (the new medina) and the Royal Palace gates.', ARRAY['en','fr','es','it','ary-Latn','ber'], 8, 2, '{}', 1, 10, 120, 2, 'active', 'https://images.pexels.com/photos/28899037/pexels-photo-28899037.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200007-cc00-0000-0000-000000000007', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Fès Borj Nord & Arms Museum', 'Guided visit to the 16th-century Borj Nord fortress and its arms museum, with panoramic medina views.', ARRAY['en','fr','es','it','ary-Latn'], 10, 2, '{}', 1, 10, 90, 2, 'active', 'https://images.pexels.com/photos/15360686/pexels-photo-15360686.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200008-cc00-0000-0000-000000000008', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Fès Jewish Mellah Walk', 'Guided walk through the historic Jewish Quarter (Mellah) of Fès, visiting the synagogue and cemetery.', ARRAY['en','fr','es','it','ary-Latn'], 10, 2, '{}', 1, 8, 90, 2, 'active', 'https://images.pexels.com/photos/35097550/pexels-photo-35097550.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200009-cc00-0000-0000-000000000009', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Fès Garden & Borj Sud Walk', 'A relaxed guided walk through the Jnan Sbil gardens and up to Borj Sud for sunset views of the medina.', ARRAY['en','fr','es','it','ary-Latn','ber'], 6, 2, '{}', 1, 12, 120, 1, 'active', 'https://images.pexels.com/photos/35070805/pexels-photo-35070805.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa20000a-cc00-0000-0000-00000000000a', 'b6666666-0000-0000-0000-000000000006', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Fès Mechoui Lunch', 'A traditional Fassi mechoui — slow-roasted lamb — served with bread, salads and mint tea.', ARRAY['en','fr','ary-Latn','ber'], 8, 1, '{}', 1, 8, 90, 2, 'active', 'https://images.pexels.com/photos/36916123/pexels-photo-36916123.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa20000b-cc00-0000-0000-00000000000b', 'b6666666-0000-0000-0000-000000000006', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Fès Medana Cooking Class & Lunch', 'Learn to cook a 3-course Moroccan meal in a medina kitchen, then eat what you make.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 1, '{}', 1, 8, 180, 2, 'active', 'https://images.pexels.com/photos/6223144/pexels-photo-6223144.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa20000c-cc00-0000-0000-00000000000c', 'b6666666-0000-0000-0000-000000000006', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Fès Breakfast & Coffee Tour', 'A morning tour of Fès''s best breakfast spots — msemen, beghrir, olive oil and coffee.', ARRAY['en','fr','ary-Latn','ber'], 8, 1, '{}', 1, 8, 90, 1, 'active', 'https://images.pexels.com/photos/18077172/pexels-photo-18077172.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa20000d-cc00-0000-0000-00000000000d', '8a9a0008-0000-0000-0000-000000000008', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Dar Attamani Budget Room (per night)', 'A simple, clean room in a Fassi guesthouse with shared bathroom and rooftop breakfast.', ARRAY['en','fr','ary-Arab','ber'], 0, 1, '{}', 1, 3, 1440, 1, 'active', 'https://images.pexels.com/photos/10573397/pexels-photo-10573397.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa20000e-cc00-0000-0000-00000000000e', '8a9a0008-0000-0000-0000-000000000008', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Dar Attamani Rooftop Suite (per night)', 'A rooftop suite with private terrace, panoramic medina views and breakfast included.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 4, 1440, 3, 'active', 'https://images.pexels.com/photos/15531325/pexels-photo-15531325.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa20000f-cc00-0000-0000-00000000000f', 'b4444444-0000-0000-0000-000000000004', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Fès Riad Palais Faraj (per night)', 'A luxury riad in a palace overlooking the medina, with pool, spa and gourmet restaurant.', ARRAY['en','fr','es','ary-Arab'], 0, 1, '{}', 1, 4, 1440, 4, 'active', 'https://images.pexels.com/photos/15531178/pexels-photo-15531178.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200010-cc00-0000-0000-000000000010', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Fès Half-Day Medina Highlights', 'A half-day tour covering the highlights: Bab Bou Jeloud, tanneries, Attarine Madrasa and souks.', ARRAY['en','fr','es','it','ary-Latn','ber'], 8, 2, '{}', 1, 12, 180, 2, 'active', 'https://images.pexels.com/photos/33514523/pexels-photo-33514523.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa200011-cc00-0000-0000-000000000011', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Fès Zellige Tile Cutting Workshop', 'Learn to cut and arrange zellige tiles with a master maalem in a traditional workshop.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 2, '{}', 1, 4, 150, 2, 'active', 'https://images.pexels.com/photos/30563521/pexels-photo-30563521.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
